import java.util.*;
import java.io.*;

public class Main {
    static class CostFlow {
        int n;
        List<Edge>[] graph;
        List<int[]> positions;
        int[] potential;
        int[] prevNode;
        int[] prevEdge;

        @SuppressWarnings("unchecked")
        public CostFlow(int nodes) {
            this.n = nodes;
            graph = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                graph[i] = new ArrayList<>();
            }
            positions = new ArrayList<>();
        }

        class Edge {
            int to, rev;
            long capacity;
            long cost;

            public Edge(int to, int rev, long capacity, long cost) {
                this.to = to;
                this.rev = rev;
                this.capacity = capacity;
                this.cost = cost;
            }
        }

        public int addEdge(int u, int v, long cap, long cst) {
            int index = positions.size();
            positions.add(new int[]{u, graph[u].size()});
            graph[u].add(new Edge(v, graph[v].size(), cap, cst));
            graph[v].add(new Edge(u, graph[u].size() - 1, 0, -cst));
            return index;
        }

        public Edge getEdge(int i) {
            int[] pos = positions.get(i);
            Edge e = graph[pos[0]].get(pos[1]);
            Edge re = graph[e.to].get(e.rev);
            return new Edge(pos[0], e.to, e.capacity + re.capacity, e.cost);
        }

        public List<Edge> allEdges() {
            List<Edge> res = new ArrayList<>();
            for (int i = 0; i < positions.size(); i++) {
                int[] pos = positions.get(i);
                Edge e = graph[pos[0]].get(pos[1]);
                Edge re = graph[e.to].get(e.rev);
                res.add(new Edge(pos[0], e.to, e.capacity + re.capacity, e.cost));
            }
            return res;
        }

        private boolean shortestPath(int s, int t) {
            long[] dist = new long[n];
            Arrays.fill(dist, Long.MAX_VALUE);
            int[] prevNode = new int[n];
            int[] prevEdge = new int[n];
            boolean[] visited = new boolean[n];
            PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            dist[s] = 0;
            this.prevNode = new int[n];
            this.prevEdge = new int[n];
            Arrays.fill(this.prevNode, -1);
            Arrays.fill(this.prevEdge, -1);
            heap.offer(new long[]{0, s});
            while (!heap.isEmpty()) {
                long[] curr = heap.poll();
                long d = curr[0];
                int v = (int) curr[1];
                if (visited[v]) continue;
                visited[v] = true;
                if (v == t) break;
                for (int i = 0; i < graph[v].size(); i++) {
                    Edge e = graph[v].get(i);
                    if (visited[e.to] || e.capacity == 0) continue;
                    long nd = d + e.cost;
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        this.prevNode[e.to] = v;
                        this.prevEdge[e.to] = i;
                        heap.offer(new long[]{nd, e.to});
                    }
                }
            }
            if (!visited[t]) return false;
            this.potential = new int[n];
            for (int v = 0; v < n; v++) {
                if (visited[v]) {
                    this.potential[v] -= dist[t];
                }
            }
            return true;
        }

        public List<long[]> minCostFlow(int s, int t, long flowLimit) {
            long flow = 0;
            long totalCost = 0;
            List<long[]> result = new ArrayList<>();
            result.add(new long[]{flow, totalCost});
            while (flow < flowLimit) {
                if (!shortestPath(s, t)) break;
                long c = flowLimit - flow;
                int v = t;
                while (v != s) {
                    int u = prevNode[v];
                    Edge e = graph[u].get(prevEdge[v]);
                    c = Math.min(c, e.capacity);
                    v = u;
                }
                v = t;
                while (v != s) {
                    int u = prevNode[v];
                    Edge e = graph[u].get(prevEdge[v]);
                    e.capacity -= c;
                    graph[v].get(e.rev).capacity += c;
                    v = u;
                }
                long delta = -potential[s];
                flow += c;
                totalCost += c * delta;
                if (result.get(result.size() - 1)[1] == totalCost) {
                    result.remove(result.size() - 1);
                }
                result.add(new long[]{flow, totalCost});
            }
            return result;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] data = br.readLine().split(" ");
        int n = Integer.parseInt(data[0]);
        int[] a = new int[3];
        int[] b = new int[3];
        data = br.readLine().split(" ");
        for (int i = 0; i < 3; i++) {
            a[i] = Integer.parseInt(data[i]);
        }
        data = br.readLine().split(" ");
        for (int i = 0; i < 3; i++) {
            b[i] = Integer.parseInt(data[i]);
        }

        CostFlow g = new CostFlow(8);
        g.addEdge(0, 1, a[0], 0);
        g.addEdge(0, 2, a[1], 0);
        g.addEdge(0, 3, a[2], 0);
        g.addEdge(4, 7, b[0], 0);
        g.addEdge(5, 7, b[1], 0);
        g.addEdge(6, 7, b[2], 0);

        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                int cst = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i, j, Long.MAX_VALUE, cst);
            }
        }

        List<long[]> res = g.minCostFlow(0, 7, (1L << 32) - 1);
        long ans1 = res.get(res.size() - 1)[0];
        long ans2 = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        System.out.println(ans1 + " " + ans2);
    }
}

